"use client";
/**
 * @file useEnhancedMeasurementCapture.ts
 * @description TASKS 010-013: Extended measurement capture hook.
 *
 * Extends useMeasurementCapture with:
 * - TASK-010: Full 10-phase CapturePhase type definition
 * - TASK-011: 30-frame landmark buffer with averaging (best-frame selection)
 * - TASK-012: Distance estimation + centering detection per frame
 * - TASK-013: Auto-advancing side pose flow with buffer reset between poses
 *
 * Architecture:
 * - Wraps useMeasurementCapture as the base (preserves all existing logic)
 * - Adds: landmarkBuffer (ref), side pose state, distance/centering helpers
 * - On submit: sends BOTH front and side landmarks to backend
 *
 * Landmark Buffer (TASK-011):
 * - Collects last 30 frames with isGoodPose
 * - On capture: averages x/y/z/visibility across all buffered frames
 * - This eliminates frame jitter for ≈10% better measurement accuracy
 *
 * Distance Detection (TASK-012):
 * - Uses normalized nose-to-ankle span in image coords
 * - too_close: span > 0.90 (fills >90% of frame)
 * - optimal:   0.70 ≤ span ≤ 0.88
 * - too_far:   span < 0.60
 *
 * Centering Detection (TASK-012):
 * - Uses normalized nose X position
 * - centered: 0.38 ≤ noseX ≤ 0.62
 *
 * Side Pose (TASK-013):
 * - Lower quality threshold: 0.75 (vs 0.85 for front)
 * - After front capture: auto-advances to 'side_transition' after 1.5s
 * - Buffer cleared between front and side captures
 */

import {
  useState,
  useCallback,
  useRef,
  useEffect,
  MutableRefObject,
} from "react";
import {
  usePoseLandmarker,
  type Landmark,
  type PoseLandmarkerResult,
} from "./usePoseLandmarker";
import { useScanSession } from "./useScanSession";
import {
  POSE_THRESHOLDS,
  CAPTURE_CONFIG,
} from "@/lib/brand";

// ─── Extended Phase Types (TASK-010) ─────────────────────────────────────────

export type EnhancedCapturePhase =
  | "idle"
  | "loading_model"
  | "device_setup"       // NEW: Phone orientation check + instructions
  | "positioning"        // NEW: User stepping into frame
  | "front_aligning"     // NEW: Quality building up for front pose
  | "front_countdown"    // NEW: Auto-capture countdown (3-2-1)
  | "front_captured"     // NEW: Front pose captured, brief confirmation
  | "side_transition"    // NEW: Instruction to turn sideways
  | "side_positioning"   // NEW: User turning and positioning for side
  | "side_aligning"      // NEW: Quality building up for side pose
  | "side_countdown"     // NEW: Side pose countdown
  | "side_captured"      // NEW: Both poses captured, submitting
  | "submitting"
  | "processing"
  | "completed"
  | "failed";

// ─── Distance / Centering Status Types ───────────────────────────────────────

export type DistanceStatus = "too_close" | "optimal" | "too_far" | "unknown";
export type CenteringStatus = "too_left" | "centered" | "too_right" | "unknown";

// ─── Frame Data ───────────────────────────────────────────────────────────────

export interface EnhancedCaptureFrame {
  quality:          number;
  isGoodPose:       boolean;
  worldLandmarks:   Landmark[] | null;
  normalLandmarks:  Landmark[] | null;
  distanceStatus:   DistanceStatus;
  centeringStatus:  CenteringStatus;
}

// ─── Return Type ──────────────────────────────────────────────────────────────

export interface UseEnhancedMeasurementCaptureReturn {
  phase:              EnhancedCapturePhase;
  currentFrame:       EnhancedCaptureFrame | null;
  sessionId:          string | null;
  sessionStatus:      import("../api/scan.api").ScanStatusResponse | null;
  error:              string | null;
  videoRef:           MutableRefObject<HTMLVideoElement | null>;
  canvasRef:          MutableRefObject<HTMLCanvasElement | null>;
  // Buffer state
  landmarkBufferSize: number;
  bufferProgress:     number;  // 0-1 progress toward stabilityFramesRequired
  // Side pose state
  isSidePosePhase:    boolean;
  hasFrontCapture:    boolean;
  // Actions
  startCapture:       (heightCm?: number, ageyears?: number) => Promise<void>;
  processFrame:       () => EnhancedCaptureFrame | null;
  triggerFrontCapture: () => void;
  triggerSideCapture:  () => void;
  advanceToSidePhase:  () => void;
  /**
   * A-1 FIX: Skip device_setup orientation check and advance directly to
   * positioning. Replaces the broken `(capture as unknown as any).setPhaseSync?("positioning")` hack.
   */
  skipDeviceSetup:    () => void;
  reset:              () => void;
  stopCamera:         () => void;
  userHeightCm:       number | null;
  /** A-5 FIX: Age in years forwarded to backend for anthropometric anchoring. */
  userAge:            number | null;
}

// ─── Landmark Buffer Averaging (TASK-011) ─────────────────────────────────────

/**
 * Compute the per-landmark average across all buffered frames.
 * Produces noise-reduced landmark set for better measurement accuracy.
 */
function computeAverageLandmarks(buffer: Landmark[][]): Landmark[] {
  if (buffer.length === 0) return [];
  const n = buffer.length;
  return buffer[0].map((_, idx) => ({
    x:          buffer.reduce((s, f) => s + (f[idx]?.x ?? 0), 0) / n,
    y:          buffer.reduce((s, f) => s + (f[idx]?.y ?? 0), 0) / n,
    z:          buffer.reduce((s, f) => s + (f[idx]?.z ?? 0), 0) / n,
    visibility: buffer.reduce((s, f) => s + (f[idx]?.visibility ?? 0), 0) / n,
  }));
}

// ─── Distance Estimation (TASK-012) ──────────────────────────────────────────

/**
 * Estimate how far the user is from the camera using normalized landmarks.
 * Compares the vertical span from nose (0) to ankle average (27/28).
 *
 * Normalized coords: 0 = top, 1 = bottom of frame.
 * A larger span = person closer to camera.
 */
function estimateDistance(normalLandmarks: Landmark[]): DistanceStatus {
  const nose       = normalLandmarks[0];
  const leftAnkle  = normalLandmarks[27];
  const rightAnkle = normalLandmarks[28];

  if (!nose || !leftAnkle || !rightAnkle) return "unknown";
  if ((nose.visibility ?? 0) < 0.5 || (leftAnkle.visibility ?? 0) < 0.3) return "unknown";

  const avgAnkleY = (leftAnkle.y + rightAnkle.y) / 2;
  const span = Math.abs(avgAnkleY - nose.y);

  if (span > 0.90) return "too_close";
  if (span >= 0.70) return "optimal";
  if (span < 0.60) return "too_far";
  return "optimal"; // 0.60-0.70: acceptable
}

// ─── Centering Detection (TASK-012) ──────────────────────────────────────────

/**
 * Detect if user is centered in the camera frame.
 * Uses nose X position in normalized coords (mirrored: 1=left, 0=right).
 */
function detectCentering(normalLandmarks: Landmark[]): CenteringStatus {
  const nose = normalLandmarks[0];
  if (!nose || (nose.visibility ?? 0) < 0.5) return "unknown";

  // Note: video is mirrored (scale-x: -1), so right/left are swapped in display
  // Actual nose X from MediaPipe: 0=left, 1=right before mirroring
  const noseX = 1 - nose.x; // After mirror correction

  if (noseX < 0.35) return "too_right";
  if (noseX > 0.65) return "too_left";
  return "centered";
}

// ─── Height estimation ────────────────────────────────────────────────────────

function estimateHeightFromLandmarks(worldLandmarks: Landmark[]): number | null {
  const nose       = worldLandmarks[0];
  const leftAnkle  = worldLandmarks[27];
  const rightAnkle = worldLandmarks[28];

  if (!nose || !leftAnkle || !rightAnkle) return null;

  const avgAnkleY = (leftAnkle.y + rightAnkle.y) / 2;
  const heightM   = Math.abs(nose.y - avgAnkleY);
  const heightCm  = heightM * 100 * 1.07; // nose-to-ankle correction factor

  if (heightCm < 120 || heightCm > 250) return null;
  return Math.round(heightCm * 10) / 10;
}

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function useEnhancedMeasurementCapture(): UseEnhancedMeasurementCaptureReturn {
  const landmarker  = usePoseLandmarker();
  const scanSession = useScanSession();

  const [phase, setPhase]               = useState<EnhancedCapturePhase>("idle");
  const [currentFrame, setCurrentFrame] = useState<EnhancedCaptureFrame | null>(null);
  const [userHeightCm, setUserHeightCm] = useState<number | null>(null);
  const [userAge, setUserAge]           = useState<number | null>(null);   // A-5 FIX
  const [error, setError]               = useState<string | null>(null);
  const [hasFrontCapture, setHasFrontCapture] = useState(false);
  const [bufferProgress, setBufferProgress]   = useState(0);

  // Camera
  const videoRef  = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  // Landmark buffers (TASK-011) — refs to avoid re-render costs per frame
  const frontBufferRef = useRef<Landmark[][]>([]);
  const sideBufferRef  = useRef<Landmark[][]>([]);
  // Final averaged landmarks to submit
  const frontLandmarksRef = useRef<Landmark[] | null>(null);
  const sideLandmarksRef  = useRef<Landmark[] | null>(null);

  const phaseRef = useRef<EnhancedCapturePhase>("idle");

  const setPhaseSync = useCallback((next: EnhancedCapturePhase) => {
    phaseRef.current = next;
    setPhase(next);
  }, []);

  // ── Sync with scan session phase ──────────────────────────────────────────
  useEffect(() => {
    if (scanSession.phase === "submitting") setPhaseSync("submitting");
    if (scanSession.phase === "processing") setPhaseSync("processing");
    if (scanSession.phase === "completed")  setPhaseSync("completed");
    if (scanSession.phase === "failed") {
      setPhaseSync("failed");
      setError(scanSession.error);
    }
  }, [scanSession.phase, scanSession.error, setPhaseSync]);

  // ── Camera start/stop ────────────────────────────────────────────────────
  const startCamera = useCallback(async () => {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 720 } },
      audio: false,
    });
    streamRef.current = stream;
    if (videoRef.current) {
      videoRef.current.srcObject = stream;
      await new Promise<void>((resolve, reject) => {
        const el = videoRef.current!;
        if (el.readyState >= 2 && el.videoWidth > 0) { resolve(); return; }
        const onCanPlay = () => { el.removeEventListener("canplay", onCanPlay); el.removeEventListener("error", onError); resolve(); };
        const onError   = (e: Event) => { el.removeEventListener("canplay", onCanPlay); el.removeEventListener("error", onError); reject(new Error(`Video error: ${(e as ErrorEvent).message ?? "unknown"}`)); };
        el.addEventListener("canplay", onCanPlay);
        el.addEventListener("error",   onError);
      });
      await videoRef.current.play();
    }
  }, []);

  const stopCamera = useCallback(() => {
    streamRef.current?.getTracks().forEach((t) => t.stop());
    streamRef.current = null;
    if (videoRef.current) videoRef.current.srcObject = null;
  }, []);

  // ── Start capture (begins with device_setup phase) ────────────────────────
  const startCapture = useCallback(
    async (heightCm?: number, ageYears?: number) => {
      setError(null);
      setPhaseSync("loading_model");

      try {
        await landmarker.initialize();
        await startCamera();
        await scanSession.initiate("web");

        if (heightCm)  setUserHeightCm(heightCm);
        if (ageYears)  setUserAge(ageYears);   // A-5 FIX: store age for submit

        setPhaseSync("device_setup"); // Show phone orientation check first
      } catch (err: unknown) {
        const msg = err instanceof Error ? err.message : "Failed to start capture.";
        setError(msg);
        setPhaseSync("failed");
        stopCamera();
      }
    },
    [landmarker, scanSession, startCamera, stopCamera, setPhaseSync]
  );

  // ── A-1 FIX: Skip device_setup orientation check ─────────────────────────
  /**
   * Advances from device_setup directly to positioning without requiring
   * the phone orientation indicator to turn green. Exposed as a proper public
   * API to replace the `(capture as unknown as any).setPhaseSync?.("positioning")`
   * hack that was silently broken because setPhaseSync is not in the return type.
   */
  const skipDeviceSetup = useCallback(() => {
    if (phaseRef.current === "device_setup" || phaseRef.current === "loading_model") {
      setPhaseSync("positioning");
    }
  }, [setPhaseSync]);

  // ── Process frame (TASKS 011, 012) ────────────────────────────────────────
  const processFrame = useCallback((): EnhancedCaptureFrame | null => {
    if (!videoRef.current || !landmarker.isReady) return null;

    const activePhases: EnhancedCapturePhase[] = [
      "positioning", "front_aligning", "front_countdown",
      "side_positioning", "side_aligning", "side_countdown",
    ];
    if (!activePhases.includes(phaseRef.current)) return null;

    const result: PoseLandmarkerResult | null = landmarker.detectFromVideo(videoRef.current);

    if (!result || !result.worldLandmarks.length) {
      const emptyFrame: EnhancedCaptureFrame = {
        quality: 0, isGoodPose: false,
        worldLandmarks: null, normalLandmarks: null,
        distanceStatus: "unknown", centeringStatus: "unknown",
      };
      setCurrentFrame(emptyFrame);
      return emptyFrame;
    }

    const worldLms  = result.worldLandmarks[0];
    const normalLms = result.landmarks[0] ?? worldLms;
    const quality   = landmarker.computeQualityScore(worldLms);

    // Height estimation
    if (!userHeightCm && quality > 0.65) {
      const estimated = estimateHeightFromLandmarks(worldLms);
      if (estimated) setUserHeightCm(estimated);
    }

    // Quality threshold depends on pose phase
    const isSide   = phaseRef.current.startsWith("side_");
    const threshold = isSide ? POSE_THRESHOLDS.sideGood : POSE_THRESHOLDS.frontGood;
    const isGoodPose = quality >= threshold;

    // TASK-011: Update landmark buffer
    const buffer = isSide ? sideBufferRef.current : frontBufferRef.current;
    if (isGoodPose) {
      buffer.push(worldLms);
      if (buffer.length > CAPTURE_CONFIG.landmarkBufferSize) {
        buffer.shift();
      }
      const progress = Math.min(1, buffer.length / CAPTURE_CONFIG.landmarkBufferSize);
      setBufferProgress(progress);
    }

    // TASK-012: Distance + centering
    const distanceStatus   = normalLms ? estimateDistance(normalLms)  : "unknown";
    const centeringStatus  = normalLms ? detectCentering(normalLms)   : "unknown";

    // Auto-advance from positioning → front_aligning when body detected
    if (phaseRef.current === "positioning" && quality > POSE_THRESHOLDS.frontMedium) {
      setPhaseSync("front_aligning");
    }
    if (phaseRef.current === "side_positioning" && quality > POSE_THRESHOLDS.sideMedium) {
      setPhaseSync("side_aligning");
    }

    const frame: EnhancedCaptureFrame = {
      quality,
      isGoodPose,
      worldLandmarks:  worldLms,
      normalLandmarks: normalLms,
      distanceStatus,
      centeringStatus,
    };
    setCurrentFrame(frame);
    return frame;
  }, [landmarker, userHeightCm, setPhaseSync]);

  // ── Front capture (TASK-013) ───────────────────────────────────────────────
  const triggerFrontCapture = useCallback(() => {
    // Save averaged front landmarks
    frontLandmarksRef.current = computeAverageLandmarks(frontBufferRef.current);
    setHasFrontCapture(true);
    setPhaseSync("front_captured");

    // Auto-advance to side_transition after delay
    setTimeout(() => {
      sideBufferRef.current  = []; // Clear buffer for side pose
      setBufferProgress(0);
      setPhaseSync("side_transition");
    }, CAPTURE_CONFIG.sideAdvanceDelay);
  }, [setPhaseSync]);

  // ── Side capture ──────────────────────────────────────────────────────────
  const triggerSideCapture = useCallback(async () => {
    sideLandmarksRef.current = computeAverageLandmarks(sideBufferRef.current);
    setPhaseSync("side_captured");

    const frontLms = frontLandmarksRef.current;
    const sideLms  = sideLandmarksRef.current;
    const height   = userHeightCm;

    if (!frontLms || !height) {
      setError("Missing front pose data. Please restart the scan.");
      setPhaseSync("failed");
      return;
    }

    // Submit both landmark sets to backend
    // A-5 FIX: Include user_age in payload so backend anthropometric anchoring works
    await scanSession.submit({
      user_height_cm: height,
      ...(userAge != null && { user_age: userAge }),
      landmarks: frontLms.map((l) => ({
        x: l.x, y: l.y, z: l.z, visibility: l.visibility ?? 0,
      })),
      // side_landmarks forwarded to backend for dual-pose fused pipeline
      ...(sideLms && {
        side_landmarks: sideLms.map((l) => ({
          x: l.x, y: l.y, z: l.z, visibility: l.visibility ?? 0,
        })),
      }),
      device_type: "web",
    });

    stopCamera();
  }, [scanSession, userHeightCm, userAge, stopCamera, setPhaseSync]);

  // ── Advance to side pose phase (manual trigger) ───────────────────────────
  const advanceToSidePhase = useCallback(() => {
    sideBufferRef.current = [];
    setBufferProgress(0);
    setPhaseSync("side_positioning");
  }, [setPhaseSync]);

  // ── Reset ─────────────────────────────────────────────────────────────────
  const reset = useCallback(() => {
    stopCamera();
    landmarker.cleanup();
    scanSession.reset();
    frontBufferRef.current = [];
    sideBufferRef.current  = [];
    frontLandmarksRef.current = null;
    sideLandmarksRef.current  = null;
    setPhaseSync("idle");
    setCurrentFrame(null);
    setUserHeightCm(null);
    setUserAge(null);
    setHasFrontCapture(false);
    setBufferProgress(0);
    setError(null);
  }, [stopCamera, landmarker, scanSession, setPhaseSync]);

  useEffect(() => () => stopCamera(), [stopCamera]);

  return {
    phase,
    currentFrame,
    sessionId:      scanSession.sessionId,
    sessionStatus:  scanSession.sessionStatus,
    error,
    videoRef,
    canvasRef,
    landmarkBufferSize: CAPTURE_CONFIG.landmarkBufferSize,
    bufferProgress,
    isSidePosePhase:   phase.startsWith("side_"),
    hasFrontCapture,
    startCapture,
    processFrame,
    triggerFrontCapture,
    triggerSideCapture,
    advanceToSidePhase,
    skipDeviceSetup,   // A-1 FIX: proper public API instead of cast hack
    reset,
    stopCamera,
    userHeightCm,
    userAge,           // A-5 FIX: exposed for any component that needs to display it
  };
}

/**
 * @file useIdleQualitySampler.ts
 * @description Phase 13 / TASK-042: Throttled, idle-aware pose quality sampler.
 *
 * Problem:
 *   - processFrame() is called every animation frame (~60fps = 16ms)
 *   - MediaPipe inference takes ~25-60ms on mobile
 *   - Running both simultaneously blocks the main thread, causing UI jank
 *
 * Solution:
 *   - Use requestIdleCallback (with setTimeout fallback) to schedule inference
 *     ONLY when the main thread has spare capacity
 *   - Cap inference at MAX_FPS_INFERENCE (default 20fps) regardless of idle time
 *   - This preserves smooth 60fps UI animations while keeping quality signal fresh
 *   - Returns a ref-based trigger — no re-renders from the sampling loop itself
 *
 * Architecture:
 *   - Caller (EnhancedMeasurementFlow) calls scheduleFrame() each rAF tick
 *   - scheduleFrame() checks if enough time has passed since last inference
 *   - If yes, schedules inference via requestIdleCallback (or setTimeout(0))
 *   - Inference result written to a ref: no setState → no re-render
 *   - Caller reads latestFrameRef.current for the latest quality reading
 *
 * Browser support:
 *   - requestIdleCallback: Chrome, Edge, Firefox 55+
 *   - Fallback: setTimeout(fn, 1) for Safari and older browsers
 */

"use client";

import { useRef, useCallback, useEffect } from "react";
import type { EnhancedCaptureFrame } from "./useEnhancedMeasurementCapture";

// ─── Config ───────────────────────────────────────────────────────────────────

const MAX_FPS_INFERENCE = 20;          // Max pose inference calls/sec
const MIN_FRAME_GAP_MS  = 1000 / MAX_FPS_INFERENCE; // 50ms between inferences
const IDLE_TIMEOUT_MS   = 100;         // requestIdleCallback timeout before forced run

// ─── Types ────────────────────────────────────────────────────────────────────

type ProcessFrameFn = () => EnhancedCaptureFrame | null;

interface UseIdleQualitySamplerReturn {
  /** Call this on every requestAnimationFrame tick */
  scheduleFrame:   () => void;
  /** Latest pose quality reading (ref — no re-render cost) */
  latestFrameRef:  React.MutableRefObject<EnhancedCaptureFrame | null>;
  /** True if an inference is currently scheduled (for debugging) */
  isPendingRef:    React.MutableRefObject<boolean>;
  /** Reset the sampler (e.g. between front/side pose phases) */
  reset:           () => void;
}

// ─── Polyfill type declarations ───────────────────────────────────────────────

// ─── Local types for the idle scheduler polyfill ─────────────────────────────
// We do NOT re-declare Window.requestIdleCallback — TypeScript's lib.dom.d.ts
// already types it. We use a local interface only for our internal use.

interface IdleDeadline {
  readonly didTimeout:  boolean;
  timeRemaining:        () => number;
}
type IdleCallbackFn = (deadline: IdleDeadline) => void;

// ─── Idle scheduler (with polyfill) ──────────────────────────────────────────

function scheduleIdle(fn: IdleCallbackFn, timeout: number): () => void {
  if (typeof window !== "undefined" && "requestIdleCallback" in window) {
    // Use the browser's native requestIdleCallback (typed via lib.dom.d.ts)
    const handle = window.requestIdleCallback(
      fn as IdleRequestCallback,
      { timeout },
    );
    return () => window.cancelIdleCallback(handle);
  }
  // Safari / older browsers: setTimeout(0) polyfill
  const id = setTimeout(() => fn({ didTimeout: true, timeRemaining: () => 0 }), 0);
  return () => clearTimeout(id);
}

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function useIdleQualitySampler(
  processFrame: ProcessFrameFn,
): UseIdleQualitySamplerReturn {
  const latestFrameRef   = useRef<EnhancedCaptureFrame | null>(null);
  const isPendingRef     = useRef<boolean>(false);
  const lastInferenceRef = useRef<number>(0);
  const cancelIdleRef    = useRef<(() => void) | null>(null);

  const reset = useCallback(() => {
    latestFrameRef.current   = null;
    isPendingRef.current     = false;
    lastInferenceRef.current = 0;
    cancelIdleRef.current?.();
    cancelIdleRef.current = null;
  }, []);

  const scheduleFrame = useCallback(() => {
    const now = performance.now();
    const elapsed = now - lastInferenceRef.current;

    // Already have a pending inference OR not enough time has passed
    if (isPendingRef.current || elapsed < MIN_FRAME_GAP_MS) return;

    isPendingRef.current = true;

    cancelIdleRef.current = scheduleIdle((_deadline) => {
      isPendingRef.current = false;
      lastInferenceRef.current = performance.now();

      try {
        const frame = processFrame();
        if (frame) latestFrameRef.current = frame;
      } catch (err) {
        // Never let inference errors crash the UI loop
        console.warn("[IdleSampler] Inference error:", err);
      }
    }, IDLE_TIMEOUT_MS);
  }, [processFrame]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cancelIdleRef.current?.();
    };
  }, []);

  return { scheduleFrame, latestFrameRef, isPendingRef, reset };
}

/**
 * @file usePoseLandmarker.ts
 * @description React hook that initialises and manages the MediaPipe Tasks Vision
 * PoseLandmarker — the NEW Tasks Vision API (replaces legacy BlazePose/Holistic).
 *
 * ── CRITICAL BUG FIXES (2026-06-29) ──────────────────────────────────────────
 *
 * BUG 1 — "ROI width and height must be > 0"
 *   MediaPipe's detectForVideo() throws an internal C++ assertion failure when
 *   the video element has videoWidth === 0 or videoHeight === 0 (i.e. the camera
 *   stream hasn't decoded its first frame yet). We MUST guard with:
 *     videoEl.readyState >= 2 && videoEl.videoWidth > 0 && videoEl.videoHeight > 0
 *   before calling detectForVideo().
 *
 * BUG 2 — Graph corruption cascade (800+ console errors)
 *   After an internal MediaPipe graph error, the graph enters a corrupted state
 *   and throws on every subsequent frame call. We detect consecutive errors and
 *   auto-reinitialize the landmarker (close + recreate) to recover cleanly.
 *
 * BUG 3 — @latest WASM URL instability
 *   Using @latest CDN URL is non-deterministic in production. Pinned to @0.10.14.
 *
 * Key features:
 * - Lazy initialisation (loads model only when called)
 * - GPU delegate with automatic CPU fallback
 * - VIDEO running mode for real-time detection
 * - Returns worldLandmarks (in metres — no pixel conversion needed)
 * - Exposes pose quality score (avg visibility of key landmarks)
 * - Auto-cleanup on unmount
 */
"use client";

import { useRef, useState, useCallback, useEffect } from "react";

// ─── MediaPipe Types (from @mediapipe/tasks-vision) ───────────────────────────

interface Landmark {
  x: number;
  y: number;
  z: number;
  visibility?: number;
}

interface PoseLandmarkerResult {
  landmarks: Landmark[][];
  worldLandmarks: Landmark[][];
  segmentationMasks?: unknown[];
}

// ─── Constants ────────────────────────────────────────────────────────────────

// Key landmark indices for quality scoring
const KEY_LANDMARK_INDICES = [
  11, 12,   // shoulders
  23, 24,   // hips
  25, 26,   // knees
  27, 28,   // ankles
];

// Pinned to a stable version — @latest causes non-deterministic WASM loads
const MEDIAPIPE_WASM_URL =
  process.env.NEXT_PUBLIC_MEDIAPIPE_WASM_URL ||
  "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14/wasm";

const POSE_MODEL_URL =
  process.env.NEXT_PUBLIC_POSE_MODEL_URL ||
  "https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_full/float16/latest/pose_landmarker_full.task";

/**
 * Maximum consecutive detectForVideo errors before we trigger graph recovery.
 * Prevents the 800+ error console flood.
 */
const MAX_CONSECUTIVE_ERRORS = 3;

// ─── Hook state types ─────────────────────────────────────────────────────────

export type LandmarkerStatus =
  | "idle"
  | "loading"
  | "ready"
  | "error";

export interface UsePoseLandmarkerReturn {
  /** Current status of the PoseLandmarker lifecycle. */
  status: LandmarkerStatus;
  /** True when the model is loaded and ready for detection. */
  isReady: boolean;
  /** Error message if initialisation failed. */
  error: string | null;
  /**
   * Load the MediaPipe Tasks Vision WASM + pose model.
   * Safe to call multiple times (idempotent).
   */
  initialize: () => Promise<void>;
  /**
   * Run pose detection on a single video frame.
   *
   * GUARDS:
   *   - Returns null if model not ready
   *   - Returns null if videoEl.readyState < 2 (no decoded frame yet)
   *   - Returns null if videoEl.videoWidth === 0 || videoEl.videoHeight === 0
   *   - Auto-reinitializes after MAX_CONSECUTIVE_ERRORS internal graph errors
   *
   * @param videoEl  The <video> element to detect from.
   * @returns PoseLandmarkerResult or null if not ready.
   */
  detectFromVideo: (videoEl: HTMLVideoElement) => PoseLandmarkerResult | null;
  /**
   * Compute the average visibility of the key body landmarks.
   * Returns 0-1. Values below 0.6 should be rejected.
   */
  computeQualityScore: (worldLandmarks: Landmark[]) => number;
  /** Release the PoseLandmarker resources. Called automatically on unmount. */
  cleanup: () => void;
}

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function usePoseLandmarker(): UsePoseLandmarkerReturn {
  const landmarkerRef        = useRef<unknown>(null);
  const consecutiveErrorsRef = useRef<number>(0);
  const isReinitializingRef  = useRef<boolean>(false);

  const [status, setStatus] = useState<LandmarkerStatus>("idle");
  const [error, setError]   = useState<string | null>(null);

  // ── Core create helper (shared by initialize + recovery) ───────────────────
  const createLandmarker = useCallback(async (): Promise<void> => {
    const { PoseLandmarker, FilesetResolver } = await import(
      "@mediapipe/tasks-vision"
    );

    const vision = await FilesetResolver.forVisionTasks(MEDIAPIPE_WASM_URL);

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const options: any = {
      baseOptions: {
        modelAssetPath: POSE_MODEL_URL,
        delegate: "GPU",  // auto-falls back to CPU on unsupported browsers
      },
      runningMode: "VIDEO" as const,
      numPoses: 1,
      minPoseDetectionConfidence: 0.65,
      minPosePresenceConfidence: 0.65,
      minTrackingConfidence: 0.65,
      outputSegmentationMasks: false,
    };

    landmarkerRef.current = await PoseLandmarker.createFromOptions(vision, options);
  }, []);

  // ── Initialize ─────────────────────────────────────────────────────────────
  const initialize = useCallback(async () => {
    if (status === "ready" || status === "loading") return;

    setStatus("loading");
    setError(null);

    try {
      await createLandmarker();
      consecutiveErrorsRef.current = 0;
      setStatus("ready");
    } catch (err: unknown) {
      const msg =
        err instanceof Error
          ? err.message
          : "Failed to initialise pose detection model.";
      setError(msg);
      setStatus("error");
      console.error("[usePoseLandmarker] Initialisation failed:", err);
    }
  }, [status, createLandmarker]);

  // ── Graph recovery (auto-reinitialize after internal error storm) ───────────
  const recoverGraph = useCallback(async () => {
    if (isReinitializingRef.current) return;
    isReinitializingRef.current = true;

    console.info("[usePoseLandmarker] Graph corrupted — recovering (close + reinit)...");

    try {
      // Close the corrupted landmarker
      if (landmarkerRef.current) {
        try {
          const lm = landmarkerRef.current as { close?: () => void };
          lm.close?.();
        } catch {
          // Ignore close errors on a corrupted graph
        }
        landmarkerRef.current = null;
      }

      // Brief pause to let WASM internals reset
      await new Promise<void>((resolve) => setTimeout(resolve, 500));

      // Recreate
      await createLandmarker();
      consecutiveErrorsRef.current = 0;
      setStatus("ready");
      console.info("[usePoseLandmarker] Graph recovery successful.");
    } catch (err) {
      console.error("[usePoseLandmarker] Graph recovery failed:", err);
      setStatus("error");
      setError("Pose detection graph failed to recover. Please refresh.");
    } finally {
      isReinitializingRef.current = false;
    }
  }, [createLandmarker]);

  // ── Detect from video ───────────────────────────────────────────────────────
  const detectFromVideo = useCallback(
    (videoEl: HTMLVideoElement): PoseLandmarkerResult | null => {
      if (!landmarkerRef.current || status !== "ready") return null;

      // ── CRITICAL GUARD: ROI width/height > 0 ──────────────────────────────
      // MediaPipe throws "roi->width > 0 && roi->height > 0" if the video
      // hasn't decoded its first frame yet (readyState < HAVE_CURRENT_DATA).
      // We MUST skip the call in this case — not doing so corrupts the graph.
      if (
        videoEl.readyState < 2 ||     // HTMLMediaElement.HAVE_CURRENT_DATA = 2
        videoEl.videoWidth  === 0 ||
        videoEl.videoHeight === 0
      ) {
        return null;  // Video not ready — silently skip this frame
      }

      // ── Skip if graph is currently being reinitialised ─────────────────────
      if (isReinitializingRef.current) return null;

      try {
        const lm = landmarkerRef.current as {
          detectForVideo: (el: HTMLVideoElement, ts: number) => PoseLandmarkerResult;
        };
        const result = lm.detectForVideo(videoEl, performance.now());
        // Success — reset error counter
        consecutiveErrorsRef.current = 0;
        return result;
      } catch (err) {
        consecutiveErrorsRef.current += 1;

        // Log the FIRST error only — suppress subsequent ones to avoid flood
        if (consecutiveErrorsRef.current === 1) {
          console.warn(
            "[usePoseLandmarker] detectForVideo error (will auto-recover):",
            err
          );
        }

        // After MAX_CONSECUTIVE_ERRORS, trigger graph recovery
        if (consecutiveErrorsRef.current >= MAX_CONSECUTIVE_ERRORS) {
          void recoverGraph();
        }

        return null;
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [status, recoverGraph]
  );

  // ── Quality score ───────────────────────────────────────────────────────────
  const computeQualityScore = useCallback(
    (worldLandmarks: Landmark[]): number => {
      if (!worldLandmarks?.length) return 0;

      const visibilities = KEY_LANDMARK_INDICES.map((idx) => {
        const lm = worldLandmarks[idx];
        return lm?.visibility ?? 0;
      });

      const avg = visibilities.reduce((a, b) => a + b, 0) / visibilities.length;
      return Math.round(avg * 100) / 100;
    },
    []
  );

  // ── Cleanup ─────────────────────────────────────────────────────────────────
  const cleanup = useCallback(() => {
    if (landmarkerRef.current) {
      try {
        const lm = landmarkerRef.current as { close?: () => void };
        lm.close?.();
      } catch {
        // Ignore cleanup errors
      }
      landmarkerRef.current = null;
      setStatus("idle");
    }
  }, []);

  // Auto-cleanup on unmount
  useEffect(() => {
    return () => cleanup();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return {
    status,
    isReady: status === "ready",
    error,
    initialize,
    detectFromVideo,
    computeQualityScore,
    cleanup,
  };
}

export type { Landmark, PoseLandmarkerResult };

